export function csvDocument(rows){const safe=value=>{let s=String(value);if(/^\s*[=+@-]/.test(s)&&numeric(s)===null)s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});}
export function plainDocument(pages){return new Blob(['\ufeff'+textPages(pages).join('\n\n\f\n\n')],{type:'text/plain;charset=utf-8'});}
